package com.sahibex.companion;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.json.*;
final class BridgeServer{
 private final SahibexAccessibilityService service;private final int port;private volatile boolean running;private ServerSocket server;private final Set<String> nonces=new HashSet<>();
 BridgeServer(SahibexAccessibilityService s,int p){service=s;port=p;}
 void start(){if(running)return;running=true;new Thread(()->{try{server=new ServerSocket(port,8,InetAddress.getByName("127.0.0.1"));while(running){Socket x=server.accept();new Thread(()->handle(x)).start();}}catch(IOException ignored){}}).start();}
 void stop(){running=false;try{if(server!=null)server.close();}catch(IOException ignored){}}
 private void handle(Socket socket){try(Socket s=socket){s.setSoTimeout(5000);BufferedReader r=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));String line;int len=0;String auth="";while((line=r.readLine())!=null&&!line.isEmpty()){String l=line.toLowerCase();if(l.startsWith("content-length:"))len=Integer.parseInt(line.substring(line.indexOf(':')+1).trim());if(l.startsWith("authorization:"))auth=line.substring(line.indexOf(':')+1).trim();}if(len<=0||len>512000){reply(s,400,new JSONObject().put("success",false).put("error","invalid body"));return;}char[] c=new char[len];if(r.read(c)!=len){reply(s,400,new JSONObject().put("success",false).put("error","incomplete body"));return;}JSONObject b=new JSONObject(new String(c));if(b.optInt("protocol_version",-1)!=1){reply(s,400,new JSONObject().put("success",false).put("error","unsupported protocol"));return;}String token=service.getSharedToken();if(token==null||!auth.equals("Bearer "+token)||!validSignature(token,b)){reply(s,401,new JSONObject().put("success",false).put("error","authentication failed"));return;}String nonce=b.optString("nonce","");synchronized(nonces){if(nonce.isEmpty()||nonces.contains(nonce)){reply(s,409,new JSONObject().put("success",false).put("error","replayed or missing nonce"));return;}nonces.add(nonce);if(nonces.size()>256)nonces.clear();}reply(s,200,new JSONObject().put("success",true).put("result",service.handle(b.getString("action"),b.optJSONObject("payload"))));}catch(Exception e){try{reply(socket,400,new JSONObject().put("success",false).put("error",e.toString()));}catch(Exception ignored){}}}
 private boolean validSignature(String token,JSONObject b)throws Exception{String canonical=b.optString("_canonical","");if(canonical.isEmpty())canonical=canonicalFallback(b);Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(token.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));byte[] raw=mac.doFinal(canonical.getBytes(StandardCharsets.UTF_8));StringBuilder h=new StringBuilder();for(byte x:raw)h.append(String.format("%02x",x));return MessageDigest.isEqual(h.toString().getBytes(StandardCharsets.UTF_8),b.optString("signature","").getBytes(StandardCharsets.UTF_8));}
 private String canonicalFallback(JSONObject b){JSONObject x=new JSONObject();x.put("action",b.optString("action"));x.put("nonce",b.optString("nonce"));x.put("payload",b.optJSONObject("payload")!=null?b.optJSONObject("payload"):new JSONObject());x.put("protocol_version",1);return x.toString();}
 private void reply(Socket s,int code,JSONObject body)throws IOException{byte[] x=body.toString().getBytes(StandardCharsets.UTF_8);OutputStream o=s.getOutputStream();o.write(("HTTP/1.1 "+code+" OK\r\nContent-Type: application/json\r\nContent-Length: "+x.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));o.write(x);o.flush();}
}
